const sparkKrantiServices=[{name:"Bengaluru–Nizamuddin Sampark Kranti Express",origin:"Bengaluru",destination:"Hazrat Nizamuddin (Delhi)",majorStations:["Guntakal","Bhopal","Jhansi","Agra"],regions:["Karnataka","Andhra Pradesh","Madhya Pradesh","Uttar Pradesh","Delhi"],description:"Connects Karnataka's state capital directly with the national capital, one of the longest-running Sampark Kranti services."},{name:"Chennai–Nizamuddin Sampark Kranti Express",origin:"Chennai Central",destination:"Hazrat Nizamuddin (Delhi)",majorStations:["Vijayawada","Nagpur","Bhopal","Jhansi"],regions:["Tamil Nadu","Andhra Pradesh","Maharashtra","Madhya Pradesh","Delhi"],description:"A superfast link between Tamil Nadu's capital and Delhi, cutting across the Deccan plateau and central India."},{name:"Kerala Sampark Kranti Express",origin:"Thiruvananthapuram",destination:"Hazrat Nizamuddin (Delhi)",majorStations:["Kozhikode","Coimbatore","Nagpur","Bhopal"],regions:["Kerala","Tamil Nadu","Maharashtra","Madhya Pradesh","Delhi"],description:"One of the longest Sampark Kranti routes, connecting Kerala's capital to Delhi across nearly the length of the country."},{name:"Bhopal–Nizamuddin Sampark Kranti Express",origin:"Rani Kamalapati (Bhopal)",destination:"Hazrat Nizamuddin (Delhi)",majorStations:["Jhansi","Gwalior","Agra"],regions:["Madhya Pradesh","Uttar Pradesh","Delhi"],description:"A relatively short, fast link giving Madhya Pradesh's capital quick, direct access to Delhi."},{name:"Jammu Tawi–Delhi Sampark Kranti Express",origin:"Jammu Tawi",destination:"New Delhi",majorStations:["Pathankot","Ludhiana","Ambala"],regions:["Jammu & Kashmir","Punjab","Haryana","Delhi"],description:"Provides fast, fully-reserved connectivity between Jammu and the national capital across the Punjab plains."}];document.addEventListener("DOMContentLoaded",()=>{const e=[{label:"Introduced",value:"2003–2004"},{label:"Service Type",value:"Superfast, Reserved"},{label:"Coach Classes",value:"Sleeper, AC 3-Tier, AC 2-Tier"},{label:"Network Hub",value:"New Delhi"}],a=document.getElementById("quick-facts-container");a&&e.forEach(e=>{const i=document.createElement("div");i.className="fact-card",i.innerHTML=`\n                <div class="fact-label">${e.label}</div>\n                <div class="fact-value">${e.value}</div>\n            `,a.appendChild(i)});const i=[{year:"2003–04",title:"Concept Introduced",description:"Sampark Kranti services were introduced to give state capitals and major cities superfast, fully-reserved connectivity to New Delhi."},{year:"Mid-2000s",title:"Network Grows",description:"New Sampark Kranti routes were added connecting cities such as Bengaluru, Chennai, Thiruvananthapuram and Bhopal to the capital."},{year:"2010s",title:"Coach Upgrades",description:"Many Sampark Kranti rakes were upgraded with LHB coaches, improving safety, ride quality and passenger amenities."},{year:"Present",title:"Ongoing Service",description:"Sampark Kranti Express services continue to operate across the country, forming a core part of India's superfast, reserved-only rail network."}],n=document.getElementById("timeline-container");n&&i.forEach(e=>{const a=document.createElement("div");a.className="timeline-item",a.tabIndex=0,a.innerHTML=`\n                <div class="timeline-year">${e.year}</div>\n                <div class="timeline-content">\n                    <h3>${e.title}</h3>\n                    <p>${e.description}</p>\n                </div>\n            `,n.appendChild(a)});const t=new IntersectionObserver(e=>{e.forEach(e=>{e.isIntersecting&&e.target.classList.add("visible")})},{threshold:.1});document.querySelectorAll(".timeline-item").forEach(e=>t.observe(e));const r=document.getElementById("services-container");r&&(r.innerHTML=sparkKrantiServices.map(e=>`\n            <div class="service-card" tabindex="0">\n                <h3>${e.name}</h3>\n                <div class="service-route">${e.origin} → ${e.destination}</div>\n                <div class="service-stations"><strong>Via:</strong> ${e.majorStations.join(", ")}</div>\n                <p class="service-desc">${e.description}</p>\n            </div>\n        `).join(""));const s=document.getElementById("routes-container");s&&(s.innerHTML=sparkKrantiServices.map(e=>`\n            <div class="route-card">\n                <div>\n                    <div class="origin-dest">${e.origin} → ${e.destination}</div>\n                    <div class="stations"><strong>Via:</strong> ${e.majorStations.join(", ")}</div>\n                </div>\n                <div class="regions-tag">${e.regions.join(" · ")}</div>\n            </div>\n        `).join(""));const o=[{icon:"🛏️",title:"Mixed Coach Classes",description:"Most rakes carry Sleeper Class, AC 3-Tier and AC 2-Tier coaches together, letting passengers choose the class that suits their budget."},{icon:"🔌",title:"Charging Points",description:"Upgraded LHB coaches include charging points at berths for mobile devices and laptops."},{icon:"🍽️",title:"Pantry & Catering",description:"Many Sampark Kranti services run a pantry car, with meals and snacks available for purchase during the journey."},{icon:"📢",title:"Passenger Information",description:"Station announcements and coach displays help passengers track the train's progress on long, multi-state journeys."},{icon:"🛡️",title:"Safety Features",description:"LHB coaches include anti-telescopic design and fire/smoke detection, along with emergency alarm chains in every coach."},{icon:"♿",title:"Reserved Seating",description:"As a fully-reserved superfast service, seating and berths are confirmed in advance, avoiding overcrowding in unreserved coaches."}],c=document.getElementById("facilities-container");c&&o.forEach(e=>{const a=document.createElement("div");a.className="facility-card",a.tabIndex=0,a.innerHTML=`\n                <div class="facility-icon" aria-hidden="true">${e.icon}</div>\n                <h3>${e.title}</h3>\n                <p>${e.description}</p>\n            `,c.appendChild(a)});const d=['"Sampark Kranti" translates from Hindi as "contact revolution," reflecting the goal of direct connectivity to the national capital.',"Unlike Rajdhani or Duronto trains, most Sampark Kranti services carry a mix of Sleeper and AC classes rather than being all-AC.","The Kerala Sampark Kranti Express, linking Thiruvananthapuram to Delhi, covers one of the longest routes in the entire Sampark Kranti network."],l=document.getElementById("trivia-container");l&&d.forEach(e=>{const a=document.createElement("div");a.className="trivia-card",a.tabIndex=0,a.innerHTML=`<p>${e}</p>`,l.appendChild(a)})});